CREATE TABLE IF NOT EXISTS schema_migrations (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, name text NOT NULL, currency text NOT NULL, timezone text NOT NULL, locale text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, type text NOT NULL CHECK(type IN ('bank','cash','savings','credit')), currency text NOT NULL, opening_balance bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
CREATE TABLE IF NOT EXISTS categories (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('income','expense','activity')), color text NOT NULL DEFAULT '#47796b', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), UNIQUE(user_id,name,kind));
CREATE TABLE IF NOT EXISTS transactions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), account_id uuid NOT NULL, category_id uuid NOT NULL, type text NOT NULL CHECK(type IN ('income','expense')), amount bigint NOT NULL CHECK(amount>0), title text NOT NULL, occurred_at timestamptz NOT NULL, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), FOREIGN KEY(account_id,user_id) REFERENCES accounts(id,user_id), FOREIGN KEY(category_id,user_id) REFERENCES categories(id,user_id));
CREATE TABLE IF NOT EXISTS budgets (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), category_id uuid NOT NULL, currency text NOT NULL, amount bigint NOT NULL CHECK(amount>0), month text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(category_id,user_id) REFERENCES categories(id,user_id), UNIQUE(user_id,category_id,currency,month));
CREATE TABLE IF NOT EXISTS activities (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), category_id uuid NOT NULL, title text NOT NULL, occurred_at timestamptz NOT NULL, duration integer NOT NULL CHECK(duration>0 AND duration<=10080), transaction_id uuid, location text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', tags text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(category_id,user_id) REFERENCES categories(id,user_id), FOREIGN KEY(transaction_id,user_id) REFERENCES transactions(id,user_id));
CREATE INDEX IF NOT EXISTS transactions_user_date ON transactions(user_id,occurred_at);
CREATE INDEX IF NOT EXISTS activities_user_date ON activities(user_id,occurred_at);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
